ceId":"media-2026073020","engagement":{},"engagementLabel":"浏览、点赞、评论未公开","discussionUrl":"https://www.axios.com/2026/07/29/anthropic-claude-open-models-ban-china","discussionFocus":["媒体报道没有公开互动指标。","“没签信”与“支持封禁开源”不是同一件事。","不同公司立场同时受安全、政策与商业模式影响。"],"reuseIdeas":["用普通用户关心的价格、选择权和安全解释路线分歧。","列清各方已公开立场。","不把争议写成单一公司阴谋。"],"localizedTranslation":"Axios报道，Anthropic没有签署支持开放权重模型的行业联名信；Dario Amodei同时表示他从未主张全面禁止开放权重模型。","analysisState":"已分析"}]')
),
incoming_drafts AS (
  SELECT value FROM json_each('[{"id":3026073004,"hotspotId":2026073004,"platform":"小红书","title":"别再囤AI课了，先用3小时判断自己缺哪一块","body":"我发现很多人学AI最容易掉进一个坑：收藏了几十门课，真正打开的没几门。\n\n今天刷到一条整理吴恩达新课程的帖子，19.5万浏览，最夸张的是收藏有5709，比点赞高一倍。大家显然都怕错过这份学习清单。\n\n但我不建议你从头到尾硬啃。先问自己现在卡在哪：不会把需求说清楚，就看提示和拆任务；会聊天但做不出东西，就看应用搭建；已经能做Demo，却总要人盯着，就看智能体怎么接着完成任务。\n\n看完只做一个小东西。比如把一份客户访谈变成摘要、FAQ和一条短视频脚本。能跑通一次，比又收藏十门课有用。\n\n这门课约3小时，不代表3小时就能转行。它更像一张地图：先帮你知道该往哪走。","visual":"4:5黑白简笔画学习地图：三个岔路牌“说清需求 / 做出应用 / 让任务连续”，右下角一只小铅笔；不使用课程视频画面。","videoScript":"别再囤AI课了。吴恩达新课程的整理帖今天有19万浏览、5709收藏，说明大家都怕错过。但这三小时不该从头硬啃。不会提需求，看提示和拆任务；会聊天却做不出东西，看应用搭建；已经能做Demo但总要人盯着，看智能体怎么连续工作。看完只做一个小项目。三小时不能让你转行，但能帮你找到自己真正缺的那一块。","version":"V1 · Codex本地化初稿","updatedBy":"Codex AI Content Operator","status":"待审核","reviewNote":""},{"id":3026073006,"hotspotId":2026073006,"platform":"小红书","title":"594GB也叫本地AI？先别急着下载","body":"今天看到一个很容易让人误会的标题：Kimi K3可以在本地跑了。\n\n听起来像普通电脑也能装。实际是，模型从1.56TB压到594GB，演示设备还是高配Mac Studio。594GB是什么概念？很多人的整台电脑硬盘也就这么大，更别说运行时还需要足够内存。\n\n这件事真正厉害的地方，是模型体积减少了约62%，还能保留一部分能力；但它离“我的笔记本离线跑满血大模型”还有很远。\n\n普通人现在选本地AI，不要先追最大的模型。先看三件事：你的机器有多少内存、任务要不要完全离线、你愿不愿意拿速度和效果换隐私。\n\n所以这不是一个立刻下载的工具推荐，而是一条很清楚的趋势：大模型正在变小，但“本地”两个字的门槛差别非常大。","visual":"4:5黑白简笔画：一个写着594GB的巨型行李箱，旁边是一台小笔记本；仅标注“体积 / 内存 / 隐私”三个词。","videoScript":"594GB也叫本地AI？Unsloth把Kimi K3从1.56TB压到594GB，帖子已经145万浏览。但别误会，这不是普通笔记本下载就能跑，演示用的是高配Mac Studio。真正的进步是体积减少约62%，不是门槛消失。普通人选本地AI先看内存、是否必须离线，以及愿不愿意牺牲速度和效果换隐私。大模型确实在变小，但“本地运行”这四个字，跨度可能从普通电脑一直到工作站。","version":"V1 · Codex本地化初稿","updatedBy":"Codex AI Content Operator","status":"待审核","reviewNote":""},{"id":3026073008,"hotspotId":2026073008,"platform":"小红书","title":"用AI找客户，最怕的不是没人回，是一眼看出你在群发","body":"今天有条帖子很热：作者让6个Claude Agent找本地商家，先选城市和行业，再检查网站、社媒和广告哪里有问题。7.6万浏览，却有632条回复，大家显然都在问这东西能不能真接到单。\n\n我觉得能抄的不是“6个Agent”，而是先诊断、再联系。\n\n别让AI抓一千个邮箱，发同一封“我们能帮你增长”。只挑10家，看看菜单打不开、预约入口藏太深、主页半年没更新，还是广告落地页对不上。然后每封只说一个你真的看见的问题，再给一个小改法。\n\nAI可以帮你整理和写初稿，但最后那一下必须像人：事实对不对，这个问题值不值得解决，对方为什么现在要理你。\n\n原帖是流程演示，不是收入证明。它能帮你更快做功课，不能替你获得信任。","visual":"4:5黑白简笔画：左边1000封相同邮件被叉掉，右边10张手写诊断卡打勾；一点圆角和小表情，不放收入数字。","videoScript":"用AI找客户，最怕的不是没人回，是一眼看出你在群发。今天一条6个Claude Agent找本地商家的帖子有632条回复。真正能抄的不是堆6个Agent，而是先诊断、再联系。只挑10家，找一个真的问题：预约入口太深、主页没更新、广告页对不上。每封邮件只说这一个问题，再给一个小改法。AI负责整理和初稿，人负责核验和信任。原帖不是收入证明，别把自动群发当成接单能力。","version":"V1 · Codex本地化初稿","updatedBy":"Codex AI Content Operator","status":"待审核","reviewNote":""},{"id":3026073010,"hotspotId":2026073010,"platform":"小红书","title":"970万浏览的“AI拆书”热帖，先别急着转","body":"今天最夸张的一条AI热帖，970多万浏览、4.7万赞。它说AI公司正在买走二手甚至稀有书，切掉书脊扫描，最后把原书打成纸浆。\n\n这个画面太有冲击力，所以特别容易转发。但我查完后，觉得要把三件事分开：\n\n能确认的：为了高速扫描而破坏书脊的做法确实有公开报道。\n\n还不能确认的：匿名批量买家是不是都属于AI公司；被毁掉的“稀有书”到底有多少。\n\n值得讨论的：当训练数据需要实体书，数字化的效率和保存原件之间，谁来定边界？\n\n所以我不会把原帖直接翻成中文发。真正有价值的不是再制造一次愤怒，而是告诉读者：哪部分有证据，哪部分只是很顺手的推断。\n\n高赞不等于完整事实。尤其是一个故事越像电影，越值得多查两步。","visual":"4:5黑白简笔画事实核查卡：一本被切开的书，旁边三枚印章“已证实 / 未证实 / 值得讨论”；不要使用真实受损书籍照片。","videoScript":"今天一条“AI公司买书拆书”的帖子冲到970万浏览。能直接照搬吗？不能。公开报道能证明，有机构会切掉书脊做高速扫描；但匿名批量买家是不是都属于AI公司，被毁的稀有书到底有多少，目前证据不够。所以这条最适合做事实核查：已证实的是破坏性扫描，未证实的是买家身份和规模，真正值得讨论的是数字化效率和保存原件的边界。高赞不等于完整事实，故事越像电影，越要多查两步。","version":"V1 · Codex本地化初稿","updatedBy":"Codex AI Content Operator","status":"待审核","reviewNote":""},{"id":3026073014,"hotspotId":2026073014,"platform":"小红书","title":"一个AI乐观派突然踩刹车，我反而想先看他怎么改观点","body":"这两年聊AI，大家很容易被逼着站队：要么相信它马上改变一切，要么觉得全是泡沫。\n\n今天看到一个原本非常看多AI的人发长帖，说自己过去半年明显变得悲观。主帖已经86万浏览、3700多赞。\n\n我暂时不想替他总结原因，因为完整线程和评论还没有全部核验。反而是“公开改观点”这件事更值得说。\n\n我们用AI也一样。半年前觉得好用的流程，可能现在发现成本太高；曾经嫌弃的工具，也可能因为一次更新突然能进工作。观点不是身份，应该跟着证据动。\n\n如果最后要把这条做成内容，我会要求自己列三栏：什么新证据让我改变；哪些担心只是猜测；什么结果出现后我会再次改回来。\n\n这比喊“AI必胜”或“AI泡沫”都难，但也更像一个真实的人。","visual":"4:5黑白简笔画：人物从“全速前进”路牌走到“先看证据”路牌，中间一个小刹车图标；文案少。","videoScript":"一个原本很看多AI的人，今天公开说自己变得更悲观，主帖已经86万浏览。我先不替他总结，因为完整线程还没核验完。但“允许自己改观点”这件事很重要。观点不是身份，应该跟着证据动。真正靠谱的复盘写三栏：什么新证据让我改变，哪些担心还只是猜测，什么结果出现后我会改回来。这比喊AI必胜或AI泡沫都难，也更像一个真实的人。","version":"V1 · Codex本地化初稿","updatedBy":"Codex AI Content Operator","status":"待审核","reviewNote":"发布前必须补完原线程和至少3条可验证评论样本。"}]')
),
current_state AS (
  SELECT payload FROM workspace_states WHERE id = 'default'
),
merged_hotspots AS (
  SELECT json_group_array(json(value)) AS items
  FROM (
    SELECT value
    FROM json_each((SELECT payload FROM current_state), '$.hotspots')
    UNION ALL
    SELECT incoming.value
    FROM incoming_hotspots AS incoming
    WHERE NOT EXISTS (
      SELECT 1
      FROM json_each((SELECT payload FROM current_state), '$.hotspots') AS existing
      WHERE json_extract(existing.value, '$.sourceUrl') =
        json_extract(incoming.value, '$.sourceUrl')
    )
  )
),
merged_drafts AS (
  SELECT json_group_array(json(value)) AS items
  FROM (
    SELECT value
    FROM json_each((SELECT payload FROM current_state), '$.drafts')
    UNION ALL
    SELECT incoming.value
    FROM incoming_drafts AS incoming
    WHERE NOT EXISTS (
      SELECT 1
      FROM json_each((SELECT payload FROM current_state), '$.drafts') AS existing
      WHERE json_extract(existing.value, '$.hotspotId') =
        json_extract(incoming.value, '$.hotspotId')
        AND json_extract(existing.value, '$.platform') =
          json_extract(incoming.value, '$.platform')
    )
  )
)
UPDATE workspace_states
SET
  payload = json_set(
    payload,
    '$.hotspots', json((SELECT items FROM merged_hotspots)),
    '$.drafts', json((SELECT items FROM merged_drafts)),
    '$.discoveryMeta', json('{"runId":"browser-social-2026-07-30-02","capturedAt":"2026-07-30T11:56:00+08:00","coverageLabel":"20条真实候选（17条增量 + 原有3条），其中15条为公开互动可核验的X/Instagram内容","gapCount":5,"editorialBrief":"不以20条作为搜索上限；持续纳入高讨论、高收藏且能讲清楚的AI内容。当天推荐8条，其余保留候选，不自动审核或发布。"}')
  ),
  updated_by = 'Codex AI Content Operator',
  updated_at = '2026-07-30T11:56:00+08:00'
WHERE id = 'default';
